## 适用场景
- 没有学校专用模板时使用
- 符合国家标准 GB/T 7713.1-2006

## 基础配置

```latex
\documentclass[12pt, a4paper]{ctexbook}

% 页面设置
\usepackage[
  top=3cm,
  bottom=2.5cm,
  left=3cm,
  right=2.5cm,
]{geometry}

% 参考文献
\usepackage[backend=biber, style=gb7714-2015]{biblatex}

% 图表标题
\usepackage{caption}
\captionsetup{
  font=small,
  labelsep=space,
  format=hang,
}

% 页眉页脚
\usepackage{fancyhdr}
\pagestyle{fancy}
\fancyhf{}
\fancyhead[C]{\leftmark}
\fancyfoot[C]{\thepage}
```

## 章节设置

```latex
% 章节标题格式
\ctexset{
  chapter = {
    format = \centering\heiti\zihao{3},
    nameformat = {},
    titleformat = {},
    number = \chinese{chapter},
    name = {第,章},
    aftername = \quad,
    beforeskip = 20pt,
    afterskip = 20pt,
  },
  section = {
    format = \heiti\zihao{4},
    aftername = \quad,
    beforeskip = 10pt,
    afterskip = 10pt,
  },
  subsection = {
    format = \heiti\zihao{-4},
    aftername = \quad,
    beforeskip = 8pt,
    afterskip = 8pt,
  },
}
```

## 图表编号

```latex
% 按章编号
\usepackage{amsmath}
\numberwithin{equation}{chapter}
\numberwithin{figure}{chapter}
\numberwithin{table}{chapter}

% 编号格式：3.1
\renewcommand{\thefigure}{\thechapter.\arabic{figure}}
\renewcommand{\thetable}{\thechapter.\arabic{table}}
\renewcommand{\theequation}{\thechapter.\arabic{equation}}
```

## 字体配置

```latex
% 确保系统有这些字体
\setCJKmainfont{SimSun}[
  BoldFont=SimHei,
  ItalicFont=KaiTi,
]
\setCJKsansfont{SimHei}
\setCJKmonofont{FangSong}

% 英文字体
\setmainfont{Times New Roman}
\setsansfont{Arial}
\setmonofont{Courier New}
```

## 编译方式

```bash
xelatex main
biber main
xelatex main
xelatex main
```

## 注意事项

1. 必须使用 XeLaTeX
2. 确保安装所需字体
3. 参考文献使用 biblatex + biber
4. 根据具体学校要求调整格式

#!/usr/bin/env python3
"""
逻辑与方法论分析器 — 中文学位论文版本

检查：段落级逻辑衔接、标题后导语完整性、方法论论证、
文献综述质量（A1/A3）、跨章节逻辑链闭合（C3）。
"""

import argparse
import re
import sys
from pathlib import Path

try:
    from parsers import extract_abstract, get_parser
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from parsers import extract_abstract, get_parser


TRANSITIONS_ZH = {
    "递进": {"此外", "进一步", "更重要的是", "不仅如此", "同时"},
    "转折": {"然而", "但是", "相反", "尽管如此", "不过"},
    "因果": {"因此", "由此可见", "故而", "所以", "从而"},
}


def _has_transition_zh(text: str) -> bool:
    return any(token in text for values in TRANSITIONS_ZH.values() for token in values)


def _needs_method_justification_zh(text: str) -> bool:
    if "本文采用" not in text and "本文使用" not in text and "我们采用" not in text:
        return False
    return not any(m in text for m in ["因为", "由于", "鉴于", "考虑到", "基于", "原因"])


# ── 文献综述质量检查 (A1, A3) ──────────────────────────────────

AUTHOR_ENUM_ZH = re.compile(
    r"^.*?[（(]\d{4}[)）].*?(?:提出|引入|设计|开发|采用|构建|建立)",
)

GAP_KEYWORDS_ZH = re.compile(
    r"(研究空白|不足|然而.*?尚未|仍然.*?(?:挑战|困难)|有待|缺乏|"
    r"尚未解决|亟待|亟需|鲜有研究|未能充分)",
)


def _check_lit_review_enumeration(lines: list[str], start: int, end: int, parser) -> list[str]:
    """A1: 检测3条及以上连续的作者/年份罗列模式。"""
    out: list[str] = []
    consecutive = 0
    streak_start = 0
    comment_prefix = parser.get_comment_prefix()
    for line_no in range(start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if not visible:
            continue
        if AUTHOR_ENUM_ZH.search(visible):
            if consecutive == 0:
                streak_start = line_no
            consecutive += 1
        else:
            if consecutive >= 3:
                out.extend(
                    [
                        f"% 文献综述（第{streak_start}-{line_no - 1}行）"
                        "[Severity: Major] [Priority: P1]: "
                        f"检测到作者/年份罗列模式（连续{consecutive}条）",
                        "% 建议：按研究主题分组，组内进行批判性对比分析。",
                        "% 理由：按时间或作者罗列文献会削弱文献综述的综合深度。",
                        "",
                    ]
                )
            consecutive = 0
    if consecutive >= 3:
        out.extend(
            [
                f"% 文献综述（第{streak_start}-{min(end, len(lines))}行）"
                "[Severity: Major] [Priority: P1]: "
                f"检测到作者/年份罗列模式（连续{consecutive}条）",
                "% 建议：按研究主题分组，组内进行批判性对比分析。",
                "% 理由：按时间或作者罗列文献会削弱文献综述的综合深度。",
                "",
            ]
        )
    return out


def _check_gap_derivation(lines: list[str], start: int, end: int, parser) -> list[str]:
    """A3: 检查相关工作末尾是否包含研究空白描述。"""
    out: list[str] = []
    scan_start = max(start, end - 10)
    comment_prefix = parser.get_comment_prefix()
    found_gap = False
    for line_no in range(scan_start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and GAP_KEYWORDS_ZH.search(visible):
            found_gap = True
            break
    if not found_gap:
        out.extend(
            [
                f"% 文献综述（第{scan_start}-{end}行）"
                "[Severity: Major] [Priority: P1]: "
                "相关工作末尾未发现研究空白推导",
                "% 建议：添加明确的研究空白陈述，连接文献综述与本文贡献。",
                "% 理由：相关工作应以识别研究空白作为结尾，为本研究提供动机。",
                "",
            ]
        )
    return out


# ── 跨章节逻辑链闭合 (C3) ──────────────────────────────────────

CONTRIBUTION_KEYWORDS_ZH = re.compile(
    r"(本文提出|本文的贡献|本文设计|本文开发|主要贡献|本研究提出|本文构建)",
)
ANSWER_KEYWORDS_ZH = re.compile(
    r"(本文证明了|实验表明|结果表明|本文提出了|验证了|证实了|研究发现)",
)

LEAD_EXEMPT_TITLES_ZH = (
    "摘要",
    "abstract",
    "参考文献",
    "bibliography",
    "致谢",
    "附录",
    "目录",
    "contents",
)
LEAD_STRUCTURAL_COMMANDS = (
    r"\chapter",
    r"\section",
    r"\subsection",
    r"\subsubsection",
    r"\paragraph",
    r"\begin{figure",
    r"\begin{table",
    r"\begin{equation",
    r"\begin{align",
    r"\begin{itemize",
    r"\begin{enumerate",
    r"\item",
)
LEAD_GUIDE_KEYWORDS_ZH = (
    "本章",
    "本节",
    "本部分",
    "本小节",
    "本小章",
    "本段",
    "下面",
    "首先",
    "然后",
    "最后",
    "具体",
    "围绕",
    "从而",
)
INTRO_BACKGROUND_RE_ZH = re.compile(r"(背景|需求|近年来|应用|场景|行业|领域|现实)")
INTRO_PROBLEM_RE_ZH = re.compile(r"(问题|挑战|瓶颈|局限|不足|困难|代价高|尚未解决)")
INTRO_PRIOR_RE_ZH = re.compile(r"(现有|已有|既有|前人|相关工作|文献|已有研究|然而|但是)")
TRIAD_PROBLEM_RE_ZH = re.compile(r"(问题|挑战|任务|目标|瓶颈|局限|研究问题)")
TRIAD_METHOD_RE_ZH = re.compile(r"(提出|设计|构建|方法|框架|模型|机制|策略)")
TRIAD_RESULT_RE_ZH = re.compile(r"(结果表明|实验表明|研究发现|提升|优于|准确率|召回率|性能|基准)")
TRIAD_CONTRIBUTION_RE_ZH = re.compile(r"(贡献|创新点|本文提出|主要贡献|本研究提出|独特之处)")
CHAPTER_BRIDGE_KEYWORDS_ZH = (
    "基于上一章",
    "承接上一章",
    "在上一章基础上",
    "在前文基础上",
    "进一步",
    "针对尚未解决",
    "围绕上述问题",
    "为解决上述问题",
    "延续前文",
)


def _section_visible_lines(
    lines: list[str], bounds: tuple[int, int], parser
) -> list[tuple[int, str]]:
    visible_lines: list[tuple[int, str]] = []
    comment_prefix = parser.get_comment_prefix()
    start, end = bounds
    for line_no in range(start, min(end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible:
            visible_lines.append((line_no, visible))
    return visible_lines


def _coverage_map_zh(text: str) -> dict[str, bool]:
    return {
        "problem": bool(TRIAD_PROBLEM_RE_ZH.search(text)),
        "method": bool(TRIAD_METHOD_RE_ZH.search(text)),
        "result": bool(TRIAD_RESULT_RE_ZH.search(text) or re.search(r"\d+(?:\.\d+)?%?", text)),
        "contribution": bool(TRIAD_CONTRIBUTION_RE_ZH.search(text)),
    }


def _check_introduction_funnel(
    lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    out: list[str] = []
    if "introduction" not in sections:
        return out

    visible_lines = _section_visible_lines(lines, sections["introduction"], parser)
    if len(visible_lines) < 3:
        return out

    first_problem = first_prior = first_contribution = None
    for line_no, visible in visible_lines:
        if first_problem is None and INTRO_PROBLEM_RE_ZH.search(visible):
            first_problem = line_no
        if first_prior is None and (
            INTRO_PRIOR_RE_ZH.search(visible) or "\\cite{" in lines[line_no - 1]
        ):
            first_prior = line_no
        if first_contribution is None and CONTRIBUTION_KEYWORDS_ZH.search(visible):
            first_contribution = line_no

    if first_contribution is None:
        return out

    if first_problem is None or first_contribution < first_problem:
        out.extend(
            [
                f"% 绪论结构（第{first_contribution}行）[Severity: Major] [Priority: P1]: "
                "绪论可能从背景直接跳到本文方案，缺少技术瓶颈铺垫",
                "% 建议：先明确主流方法解决不了什么，再提出本文研究问题或方法。",
                "% 理由：绪论应按背景→瓶颈→前人不足→本文工作的漏斗链展开。",
                "",
            ]
        )

    if first_problem is not None and first_prior is None:
        out.extend(
            [
                f"% 绪论结构（第{first_problem}行）[Severity: Major] [Priority: P1]: "
                "绪论提出了问题，但没有从前人工作不足推导该问题",
                "% 建议：补充已有工作的尝试与局限，再落到本文研究动机。",
                "% 理由：只有问题没有前人不足，会让研究动机显得突兀。",
                "",
            ]
        )
    elif (
        first_problem is not None
        and first_prior is not None
        and first_contribution is not None
        and first_prior > first_contribution
    ):
        out.extend(
            [
                f"% 绪论结构（第{first_contribution}行）[Severity: Major] [Priority: P1]: "
                "本文工作出现在前人不足之前，绪论漏斗链顺序可能错误",
                "% 建议：先交代已有方法的不足，再引出本文方法。",
                "% 理由：研究问题和方法应建立在明确的文献缺口之上。",
                "",
            ]
        )
    return out


def _check_tri_section_alignment(
    content: str, lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    out: list[str] = []
    if "conclusion" not in sections:
        return out

    abstract_text = extract_abstract(content)
    if not abstract_text:
        return out

    contribution_key = "contribution" if "contribution" in sections else "introduction"
    if contribution_key not in sections:
        return out

    contribution_text = " ".join(
        text for _, text in _section_visible_lines(lines, sections[contribution_key], parser)
    )
    conclusion_text = " ".join(
        text for _, text in _section_visible_lines(lines, sections["conclusion"], parser)
    )
    if not contribution_text or not conclusion_text:
        return out

    coverage = {
        "abstract": _coverage_map_zh(abstract_text),
        "contribution_source": _coverage_map_zh(contribution_text),
        "conclusion": _coverage_map_zh(conclusion_text),
    }
    required_facets = {
        facet
        for facet in ("problem", "method", "result", "contribution")
        if sum(1 for sec in coverage.values() if sec[facet]) >= 2
    }
    mismatches: list[str] = []
    for section_name, section_coverage in coverage.items():
        missing = sorted(facet for facet in required_facets if not section_coverage[facet])
        if len(missing) >= 2 or (
            section_name in {"abstract", "conclusion"}
            and ("result" in missing or "contribution" in missing)
        ):
            mismatches.append(f"{section_name} 缺少 {', '.join(missing)}")

    if coverage["contribution_source"]["contribution"]:
        if not coverage["abstract"]["contribution"]:
            mismatches.append("abstract 缺少贡献表述")
        if not coverage["conclusion"]["contribution"]:
            mismatches.append("conclusion 缺少贡献回应")
    if coverage["abstract"]["method"] and not coverage["conclusion"]["result"]:
        mismatches.append("conclusion 缺少结果支撑")

    if mismatches:
        out.extend(
            [
                "% 跨章节一致性 [Severity: Major] [Priority: P1]: 摘要、创新点/贡献来源、结论之间可能存在错位",
                f"% 观察：{'；'.join(mismatches)}。",
                "% 建议：三处都要围绕研究问题、方法、核心结果、增量贡献形成对应关系。",
                "% 理由：摘要、创新点与结论应长得像但不应各说各话。",
                "",
            ]
        )
    return out


def _check_chapter_mainline(content: str, lines: list[str], parser) -> list[str]:
    """Check whether major chapters are bridged into one thesis storyline."""
    out: list[str] = []
    headings = [h for h in parser.extract_headings(content) if h["level"] == 1]
    if len(headings) < 3:
        return out

    substantive = [
        h
        for h in headings
        if not _is_exempt_heading(h["title"])
        and "结论" not in h["title"]
        and "总结" not in h["title"]
    ]
    if len(substantive) < 3:
        return out

    missing_bridges: list[str] = []
    for heading in substantive[1:]:
        start_line = heading["line"] + 1
        lead_text = ""
        for line_no in range(start_line, min(start_line + 8, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            kind = _classify_lead_gap(raw)
            if kind in {"empty", "comment", "structural"}:
                continue
            visible = parser.extract_visible_text(raw)
            if visible:
                lead_text = visible
                break
        if not lead_text:
            continue
        has_bridge = any(keyword in lead_text for keyword in CHAPTER_BRIDGE_KEYWORDS_ZH)
        generic_chapter_open = lead_text.startswith("本章") or lead_text.startswith("本文")
        if not has_bridge and generic_chapter_open:
            missing_bridges.append(f"{heading['title']}（第{heading['line']}行）")

    if len(missing_bridges) >= 2:
        out.extend(
            [
                "% 章节主线 [Severity: Major] [Priority: P1]: 多个核心章节缺少与前章结论的桥接，整体主线可能偏向工作罗列",
                f"% 观察：{', '.join(missing_bridges)} 的开头未明确承接上一章或说明递进关系。",
                "% 建议：在章节引言或本章小结中显式写出“基于上一章……本章进一步……”。",
                "% 理由：学位论文需要体现递进或并列互补的系统性，而不是可任意换序的工作堆砌。",
                "",
            ]
        )
    return out


def _check_cross_section_closure(
    lines: list[str], sections: dict[str, tuple[int, int]], parser
) -> list[str]:
    """C3: 验证绪论中的贡献声明在结论中得到回应。"""
    out: list[str] = []
    if "introduction" not in sections or "conclusion" not in sections:
        return out

    intro_start, intro_end = sections["introduction"]
    concl_start, concl_end = sections["conclusion"]
    comment_prefix = parser.get_comment_prefix()

    intro_claims = 0
    for line_no in range(intro_start, min(intro_end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and CONTRIBUTION_KEYWORDS_ZH.search(visible):
            intro_claims += 1

    if intro_claims == 0:
        return out

    concl_answers = 0
    for line_no in range(concl_start, min(concl_end, len(lines)) + 1):
        raw = lines[line_no - 1].strip()
        if not raw or raw.startswith(comment_prefix):
            continue
        visible = parser.extract_visible_text(raw)
        if visible and ANSWER_KEYWORDS_ZH.search(visible):
            concl_answers += 1

    if concl_answers == 0:
        out.extend(
            [
                f"% 逻辑衔接（第{concl_start}-{concl_end}行）"
                "[Severity: Major] [Priority: P1]: "
                "[Script] 跨章节逻辑链可能不完整",
                f"% 观察：绪论中有{intro_claims}处贡献声明，但结论中未发现明确回应。",
                "% 建议：在结论中添加明确回应每项贡献的陈述。",
                "% 理由：结论应当闭合绪论中开启的逻辑链。",
                "",
            ]
        )
    return out


def _is_exempt_heading(title: str) -> bool:
    normalized = title.strip().lower()
    return any(token in normalized for token in LEAD_EXEMPT_TITLES_ZH)


def _classify_lead_gap(line: str) -> str:
    stripped = line.strip()
    if not stripped:
        return "empty"
    if stripped.startswith("%") or stripped.startswith("//"):
        return "comment"
    if any(stripped.startswith(token) for token in LEAD_STRUCTURAL_COMMANDS):
        return "structural"
    return "text"


def _check_heading_leads(content: str, lines: list[str], parser) -> list[str]:
    """检查标题后是否先给出导语段落，而不是直接跳入结构元素。"""
    out: list[str] = []
    headings = parser.extract_headings(content)
    if not headings:
        return out

    for index, heading in enumerate(headings):
        title = heading["title"]
        if _is_exempt_heading(title):
            continue

        start_line = heading["line"] + 1
        end_line = headings[index + 1]["line"] - 1 if index + 1 < len(headings) else len(lines)
        if start_line > end_line:
            out.extend(
                [
                    f"% 结构衔接（第{heading['line']}行）[Severity: Major] [Priority: P1]: "
                    f"标题“{title}”后未发现导语段落",
                    "% 建议：在标题后先用一段导语交代本层级的研究对象、写作目的和行文安排。",
                    "% 理由：标题后直接结束或切到下一级标题，会导致结构展开过于突兀。",
                    "",
                ]
            )
            continue

        first_text_line = None
        first_structural_line = None
        first_text = ""
        for line_no in range(start_line, min(end_line, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            kind = _classify_lead_gap(raw)
            if kind in {"empty", "comment"}:
                continue
            if kind == "structural":
                first_structural_line = line_no
                break

            visible = parser.extract_visible_text(raw)
            if visible:
                first_text_line = line_no
                first_text = visible
                break

        if first_text_line is None:
            reason = (
                f"标题后直接进入结构元素（第{first_structural_line}行）"
                if first_structural_line
                else "标题后未发现可见正文"
            )
            out.extend(
                [
                    f"% 结构衔接（第{heading['line']}行）[Severity: Major] [Priority: P1]: "
                    f"标题“{title}”后缺少导语段落",
                    f"% 观察：{reason}。",
                    "% 建议：先补一段完整导语，再进入列表、图表、公式或下一级标题。",
                    "% 理由：章节、小节和四级标题展开时应先说明本段写什么、为何写、如何组织。",
                    "",
                ]
            )
            continue

        is_short = len(first_text) < 18
        has_guide_signal = any(keyword in first_text for keyword in LEAD_GUIDE_KEYWORDS_ZH)
        if heading["level"] <= 4 and is_short and not has_guide_signal:
            out.extend(
                [
                    f"% 结构衔接（第{first_text_line}行）[Severity: Minor] [Priority: P2]: "
                    f"标题“{title}”后的导语可能过短",
                    f"% 原文: {first_text}",
                    "% 建议：扩展为一段完整导语，交代本层级内容范围、与上文关系及展开顺序。",
                    "% 理由：过短句子难以承担章节导入和逻辑承接功能。",
                    "",
                ]
            )
    return out


def analyze(file_path: Path, section: str | None = None, cross_section: bool = False) -> list[str]:
    parser = get_parser(file_path)
    content = file_path.read_text(encoding="utf-8", errors="ignore")
    lines = content.split("\n")
    sections = parser.split_sections(content)

    if section:
        key = section.lower()
        if key not in sections:
            return [f"% ERROR [Severity: Critical] [Priority: P0]: 未找到章节: {section}"]
        ranges = [sections[key]]
    else:
        ranges = list(sections.values()) if sections else [(1, len(lines))]

    out: list[str] = []
    previous_visible = ""
    comment_prefix = parser.get_comment_prefix()
    for start, end in ranges:
        for line_no in range(start, min(end, len(lines)) + 1):
            raw = lines[line_no - 1].strip()
            if not raw or raw.startswith(comment_prefix):
                continue

            visible = parser.extract_visible_text(raw)
            if not visible:
                continue

            if _needs_method_justification_zh(visible):
                out.extend(
                    [
                        f"% 方法论深度（第{line_no}行）[Severity: Major] [Priority: P1]: "
                        "方法选择缺乏论证",
                        f"% 原文: {visible}",
                        "% 建议：添加选择理由（如效率/准确率/可复现性）。",
                        "% 理由：方法选择应说明为何采用该方案。",
                        "",
                    ]
                )

            if (
                previous_visible
                and not _has_transition_zh(visible)
                and any(k in previous_visible for k in ["问题", "挑战", "困难", "噪声"])
                and any(k in visible for k in ["本文提出", "本文设计", "我们的方法"])
            ):
                out.extend(
                    [
                        f"% 逻辑衔接（第{line_no}行）[Severity: Major] [Priority: P1]: "
                        "问题与解决方案间可能存在逻辑跳跃",
                        f"% 原文: {visible}",
                        '% 建议：添加显式过渡（如"因此"、"为解决上述问题"）。',
                        "% 理由：增强段落间的逻辑连贯性。",
                        "",
                    ]
                )

            previous_visible = visible

    # ── 章节级检查 ─────────────────────────────────────────────
    if not section:
        out.extend(_check_heading_leads(content, lines, parser))
        out.extend(_check_chapter_mainline(content, lines, parser))

    if sections:
        if not section and "introduction" in sections:
            out.extend(_check_introduction_funnel(lines, sections, parser))

        related_key = "related"
        if related_key in sections:
            r_start, r_end = sections[related_key]
            if not section or section.lower() == related_key:
                out.extend(_check_lit_review_enumeration(lines, r_start, r_end, parser))
                out.extend(_check_gap_derivation(lines, r_start, r_end, parser))

        if cross_section and not section:
            out.extend(_check_cross_section_closure(lines, sections, parser))
        if not section:
            out.extend(_check_tri_section_alignment(content, lines, sections, parser))

    if not out:
        out.append("% 逻辑/方法论：未检测到规则级逻辑问题。")
    return out


def main() -> int:
    cli = argparse.ArgumentParser(description="中文学位论文逻辑与方法论分析")
    cli.add_argument("file", type=Path, help="目标 .tex/.typ 文件")
    cli.add_argument("--section", help="指定分析章节")
    cli.add_argument(
        "--cross-section",
        action="store_true",
        help="启用跨章节逻辑链闭合检查",
    )
    args = cli.parse_args()

    if not args.file.exists():
        print(f"[错误] 文件未找到: {args.file}", file=sys.stderr)
        return 1

    print("\n".join(analyze(args.file, args.section, args.cross_section)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
Terminology Consistency Checker - Check term usage consistency in thesis

Usage:
    uv run python check_consistency.py main.tex
    uv run python check_consistency.py main.tex --terms
    uv run python check_consistency.py main.tex --abbreviations
"""

import argparse
import re
import sys
from collections import defaultdict
from pathlib import Path


class ConsistencyChecker:
    """Check terminology and abbreviation consistency across thesis files."""

    # Built-in example term groups (common CS/AI terms)
    DEFAULT_TERM_GROUPS_ZH = [
        ["深度学习", "深度神经网络", "深层学习"],
        ["机器学习", "机器智能"],
        ["卷积神经网络", "卷积网络", "CNN"],
        ["循环神经网络", "递归神经网络", "RNN"],
        ["长短期记忆", "LSTM"],
        ["生成对抗网络", "GAN"],
        ["自然语言处理", "NLP"],
        ["计算机视觉", "CV"],
        ["强化学习", "RL"],
    ]

    DEFAULT_TERM_GROUPS_EN = [
        ["deep learning", "deep neural network"],
        ["machine learning", "ML"],
        ["convolutional neural network", "CNN"],
        ["recurrent neural network", "RNN"],
        ["long short-term memory", "LSTM"],
        ["generative adversarial network", "GAN"],
        ["natural language processing", "NLP"],
    ]

    def __init__(self, tex_files: list[str], custom_terms_file: str | None = None):
        self.tex_files = [Path(f).resolve() for f in tex_files]
        self.content_cache: dict[Path, str] = {}
        self.term_groups_zh = list(self.DEFAULT_TERM_GROUPS_ZH)
        self.term_groups_en = list(self.DEFAULT_TERM_GROUPS_EN)
        if custom_terms_file:
            self._load_custom_terms(custom_terms_file)

    def _load_custom_terms(self, path: str) -> None:
        """Load custom term groups from a JSON file.

        Expected format: {"zh": [["termA", "termB"], ...], "en": [["termC", "termD"], ...]}
        """
        import json

        try:
            data = json.loads(Path(path).read_text(encoding="utf-8"))
            if "zh" in data:
                self.term_groups_zh.extend(data["zh"])
            if "en" in data:
                self.term_groups_en.extend(data["en"])
        except Exception as e:
            print(f"[WARNING] Failed to load custom terms: {e}", file=sys.stderr)

    def _load_content(self, tex_file: Path) -> str:
        """Load and cache file content."""
        if tex_file not in self.content_cache:
            try:
                self.content_cache[tex_file] = tex_file.read_text(encoding="utf-8", errors="ignore")
            except Exception:
                self.content_cache[tex_file] = ""
        return self.content_cache[tex_file]

    def check_terms(self) -> dict:
        """Check term consistency across files."""
        term_occurrences: dict[str, list[tuple[str, int]]] = defaultdict(list)

        for tex_file in self.tex_files:
            content = self._load_content(tex_file)
            if not content:
                continue

            # Check each term group
            all_groups = self.term_groups_zh + self.term_groups_en

            for group in all_groups:
                for term in group:
                    # Find all occurrences
                    pattern = re.escape(term)
                    matches = list(re.finditer(pattern, content, re.IGNORECASE))
                    if matches:
                        for match in matches:
                            # Find line number
                            line_num = content[: match.start()].count("\n") + 1
                            term_occurrences[term].append((str(tex_file.name), line_num))

        # Find inconsistencies
        inconsistencies = []
        checked_groups: set[frozenset] = set()

        all_groups = self.term_groups_zh + self.term_groups_en

        for group in all_groups:
            group_set = frozenset(group)
            if group_set in checked_groups:
                continue
            checked_groups.add(group_set)

            found_terms = {}
            for term in group:
                if term in term_occurrences:
                    found_terms[term] = len(term_occurrences[term])

            if len(found_terms) > 1:
                # Multiple variants used
                most_common = max(found_terms.items(), key=lambda x: x[1])
                inconsistencies.append(
                    {
                        "group": list(found_terms.keys()),
                        "counts": found_terms,
                        "suggestion": f"统一使用 '{most_common[0]}'",
                    }
                )

        return {
            "term_occurrences": {k: len(v) for k, v in term_occurrences.items()},
            "inconsistencies": inconsistencies,
            "status": "PASS" if not inconsistencies else "WARNING",
        }

    def check_abbreviations(self) -> dict:
        """Check abbreviation definitions and usage."""
        # Pattern for abbreviation definition: 全称（缩写）or 全称 (abbreviation)
        definition_pattern = r"([^（(]+)[（(]([A-Z]{2,})[）)]"

        definitions: dict[str, list[tuple[str, str, int]]] = defaultdict(list)
        usages: dict[str, list[tuple[str, int]]] = defaultdict(list)

        for tex_file in self.tex_files:
            content = self._load_content(tex_file)
            if not content:
                continue

            # Find definitions
            for match in re.finditer(definition_pattern, content):
                full_name = match.group(1).strip()
                abbrev = match.group(2)
                line_num = content[: match.start()].count("\n") + 1
                definitions[abbrev].append((full_name, str(tex_file.name), line_num))

            # Find standalone abbreviation usages
            # Look for uppercase sequences that might be abbreviations
            abbrev_pattern = r"\b([A-Z]{2,})\b"
            for match in re.finditer(abbrev_pattern, content):
                abbrev = match.group(1)
                # Skip common non-abbreviation uppercase
                if abbrev in ["PDF", "URL", "HTTP", "HTTPS", "API", "TODO", "FIXME"]:
                    continue
                line_num = content[: match.start()].count("\n") + 1
                usages[abbrev].append((str(tex_file.name), line_num))

        # Find issues
        issues = []

        # Abbreviations used but not defined
        for abbrev, usage_list in usages.items():
            if abbrev not in definitions and len(usage_list) > 0:
                first_usage = usage_list[0]
                issues.append(
                    {
                        "type": "undefined",
                        "abbreviation": abbrev,
                        "first_usage": first_usage,
                        "usage_count": len(usage_list),
                        "message": f"'{abbrev}' used but not defined (first at {first_usage[0]}:{first_usage[1]})",
                    }
                )

        # Abbreviations defined multiple times
        for abbrev, def_list in definitions.items():
            if len(def_list) > 1:
                issues.append(
                    {
                        "type": "multiple_definitions",
                        "abbreviation": abbrev,
                        "definitions": def_list,
                        "message": f"'{abbrev}' defined {len(def_list)} times",
                    }
                )

        return {
            "definitions": {k: len(v) for k, v in definitions.items()},
            "usages": {k: len(v) for k, v in usages.items()},
            "issues": issues,
            "status": "PASS" if not issues else "WARNING",
        }

    def generate_report(self, terms_result: dict, abbrev_result: dict) -> str:
        """Generate human-readable report."""
        lines = []
        lines.append("=" * 60)
        lines.append("Consistency Check Report / 一致性检查报告")
        lines.append("=" * 60)

        # Term consistency
        lines.append("\n[1] Term Consistency / 术语一致性")
        lines.append("-" * 40)

        if terms_result["inconsistencies"]:
            lines.append(f"Status: ⚠️ {len(terms_result['inconsistencies'])} inconsistencies found")
            for inc in terms_result["inconsistencies"]:
                lines.append(f"\n  Group: {', '.join(inc['group'])}")
                for term, count in inc["counts"].items():
                    lines.append(f"    - '{term}': {count} times")
                lines.append(f"  Suggestion: {inc['suggestion']}")
        else:
            lines.append("Status: ✅ No inconsistencies found")

        # Abbreviation check
        lines.append("\n[2] Abbreviation Check / 缩略语检查")
        lines.append("-" * 40)

        if abbrev_result["issues"]:
            lines.append(f"Status: ⚠️ {len(abbrev_result['issues'])} issues found")
            for issue in abbrev_result["issues"]:
                lines.append(f"\n  [{issue['type']}] {issue['message']}")
        else:
            lines.append("Status: ✅ All abbreviations properly defined")

        lines.append("\n" + "=" * 60)
        return "\n".join(lines)


def find_tex_files(main_file: str) -> list[str]:
    """Find all .tex files in the project."""
    main_path = Path(main_file).resolve()
    root_dir = main_path.parent

    # Find all .tex files
    tex_files = list(root_dir.rglob("*.tex"))

    # Also check common subdirectories
    for subdir in ["data", "chapters", "sections", "content"]:
        subdir_path = root_dir / subdir
        if subdir_path.exists():
            tex_files.extend(subdir_path.rglob("*.tex"))

    # Remove duplicates and sort
    tex_files = sorted(set(tex_files))

    return [str(f) for f in tex_files]


def main():
    parser = argparse.ArgumentParser(description="Terminology Consistency Checker")
    parser.add_argument("tex_file", help="Main .tex file or directory")
    parser.add_argument("--terms", "-t", action="store_true", help="Check only term consistency")
    parser.add_argument(
        "--abbreviations", "-a", action="store_true", help="Check only abbreviation consistency"
    )
    parser.add_argument("--json", "-j", action="store_true", help="Output in JSON format")
    parser.add_argument("--custom-terms", type=str, help="JSON file with custom term groups")

    args = parser.parse_args()

    # Find tex files
    if Path(args.tex_file).is_dir():
        tex_files = [str(p) for p in Path(args.tex_file).rglob("*.tex")]
    else:
        if not Path(args.tex_file).exists():
            print(f"[ERROR] File not found: {args.tex_file}", file=sys.stderr)
            sys.exit(1)
        tex_files = find_tex_files(args.tex_file)

    if not tex_files:
        print("[ERROR] No .tex files found", file=sys.stderr)
        sys.exit(1)

    print(f"[INFO] Checking {len(tex_files)} files...")

    # Run checks
    checker = ConsistencyChecker(tex_files, custom_terms_file=args.custom_terms)

    if args.terms:
        result = checker.check_terms()
        if args.json:
            import json

            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"\nTerm consistency: {result['status']}")
            for inc in result["inconsistencies"]:
                print(f"  - {inc['suggestion']}")
        sys.exit(0)

    if args.abbreviations:
        result = checker.check_abbreviations()
        if args.json:
            import json

            print(json.dumps(result, indent=2, ensure_ascii=False))
        else:
            print(f"\nAbbreviation check: {result['status']}")
            for issue in result["issues"]:
                print(f"  - {issue['message']}")
        sys.exit(0)

    # Full check
    terms_result = checker.check_terms()
    abbrev_result = checker.check_abbreviations()

    if args.json:
        import json

        output = {
            "terms": terms_result,
            "abbreviations": abbrev_result,
        }
        print(json.dumps(output, indent=2, ensure_ascii=False))
    else:
        print(checker.generate_report(terms_result, abbrev_result))

    # Exit code
    if terms_result["status"] != "PASS" or abbrev_result["status"] != "PASS":
        sys.exit(1)
    sys.exit(0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
LaTeX Format Checker (Chinese) - chktex wrapper with Chinese support

Usage:
    uv run python check_format.py main.tex
    uv run python check_format.py main.tex --strict
"""

import argparse
import re
import shutil
import subprocess
import sys
from pathlib import Path
from typing import Optional


class FormatChecker:
    """ChkTeX wrapper with Chinese thesis specific checks."""

    # Chinese-specific checks (in addition to chktex)
    CHINESE_CHECKS = {
        "mixed_punctuation": {
            "pattern": r"[\u4e00-\u9fff][,.:;!?]|[,.:;!?][\u4e00-\u9fff]",
            "message": "Mixed Chinese/English punctuation detected",
            "severity": "warning",
        },
        "missing_space_after_cite": {
            "pattern": r"\\cite\{[^}]+\}[\u4e00-\u9fff]",
            "message": "Missing space after \\cite before Chinese text",
            "severity": "info",
        },
        "oral_expression": {
            "pattern": r"我们|你们|很多|一些|非常|特别",
            "message": "Potential oral expression in academic writing",
            "severity": "warning",
        },
    }

    def __init__(self, tex_file: str, config: Optional[str] = None):
        self.tex_file = Path(tex_file).resolve()
        self.work_dir = self.tex_file.parent
        self.config = config

    def _check_chktex(self) -> tuple[bool, str]:
        """Check if chktex is available."""
        if shutil.which("chktex"):
            return True, "chktex is available"
        return False, "chktex not found"

    def check(self, strict: bool = False) -> dict:
        """Run format checks including Chinese-specific ones."""
        all_issues = []

        # Run chktex if available
        ok, msg = self._check_chktex()
        if ok:
            chktex_issues = self._run_chktex(strict)
            all_issues.extend(chktex_issues)

        # Run Chinese-specific checks
        chinese_issues = self._run_chinese_checks()
        all_issues.extend(chinese_issues)

        return {
            "status": "PASS" if not all_issues else "WARNING",
            "chktex_available": ok,
            "issues": all_issues,
            "total": len(all_issues),
        }

    def _run_chktex(self, strict: bool) -> list[dict]:
        """Run chktex and parse output."""
        cmd = ["chktex"]
        if strict:
            cmd.extend(["-v3"])
        else:
            cmd.extend(["-v0", "-q"])
        cmd.append(str(self.tex_file))

        try:
            result = subprocess.run(
                cmd,
                cwd=self.work_dir,
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
            )
            return self._parse_chktex_output(result.stdout + result.stderr)
        except Exception:
            return []

    def _parse_chktex_output(self, output: str) -> list[dict]:
        """Parse chktex output."""
        issues = []
        pattern = r"(.+?):(\d+):(\d+):\s*(Warning|Error)\s*(\d+):\s*(.+)"

        for line in output.split("\n"):
            match = re.match(pattern, line.strip())
            if match:
                issues.append(
                    {
                        "source": "chktex",
                        "file": match.group(1),
                        "line": int(match.group(2)),
                        "column": int(match.group(3)),
                        "severity": match.group(4).lower(),
                        "code": int(match.group(5)),
                        "message": match.group(6),
                    }
                )

        return issues

    def _run_chinese_checks(self) -> list[dict]:
        """Run Chinese-specific checks."""
        issues = []

        try:
            content = self.tex_file.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            return issues

        lines = content.split("\n")

        for check_name, check_info in self.CHINESE_CHECKS.items():
            pattern = check_info["pattern"]

            for i, line in enumerate(lines, 1):
                # Skip comments
                if line.strip().startswith("%"):
                    continue

                for match in re.finditer(pattern, line):
                    issues.append(
                        {
                            "source": "chinese_check",
                            "file": str(self.tex_file.name),
                            "line": i,
                            "column": match.start() + 1,
                            "severity": check_info["severity"],
                            "code": check_name,
                            "message": check_info["message"],
                            "matched": match.group(),
                        }
                    )

        return issues

    def generate_report(self, result: dict) -> str:
        """Generate human-readable report."""
        lines = []
        lines.append("=" * 60)
        lines.append("LaTeX Format Check Report (Chinese Thesis)")
        lines.append("=" * 60)
        lines.append(f"File: {self.tex_file}")
        lines.append(f"Status: {result['status']}")
        lines.append(f"ChkTeX: {'Available' if result['chktex_available'] else 'Not Available'}")
        lines.append(f"Total Issues: {result['total']}")

        if result["issues"]:
            lines.append("")
            lines.append("-" * 60)
            lines.append("Issues:")
            lines.append("-" * 60)

            # Group by source
            by_source = {}
            for issue in result["issues"]:
                source = issue["source"]
                if source not in by_source:
                    by_source[source] = []
                by_source[source].append(issue)

            for source, issues in by_source.items():
                lines.append(f"\n[{source.upper()}] ({len(issues)} issues)")
                for issue in issues[:10]:
                    sev = issue["severity"].upper()
                    lines.append(f"  [{sev}] Line {issue['line']}: {issue['message']}")
                if len(issues) > 10:
                    lines.append(f"  ... and {len(issues) - 10} more")

        lines.append("")
        lines.append("=" * 60)
        return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description="LaTeX Format Checker (Chinese Thesis)")
    parser.add_argument("tex_file", help=".tex file to check")
    parser.add_argument("--strict", "-s", action="store_true", help="Enable strict checking")
    parser.add_argument("--json", "-j", action="store_true", help="Output in JSON format")

    args = parser.parse_args()

    if not Path(args.tex_file).exists():
        print(f"[ERROR] File not found: {args.tex_file}")
        sys.exit(1)

    checker = FormatChecker(args.tex_file)
    result = checker.check(strict=args.strict)

    if args.json:
        import json

        print(json.dumps(result, indent=2, ensure_ascii=False))
    else:
        print(checker.generate_report(result))

    sys.exit(0 if result["status"] == "PASS" else 1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Table Structure Checker - Validate three-line table compliance in LaTeX documents.

Usage:
    uv run python -B check_tables.py main.tex
    uv run python -B check_tables.py main.tex --fix-suggestions
    uv run python -B check_tables.py main.tex --json
"""

import argparse
import json
import re
import sys
from pathlib import Path


class TableChecker:
    """Validate LaTeX tables against the three-line (booktabs) standard."""

    LEVEL_ERROR = "ERROR"
    LEVEL_WARNING = "WARNING"
    LEVEL_INFO = "INFO"

    # Booktabs commands that define valid three-line rules
    VALID_RULES = {r"\toprule", r"\midrule", r"\bottomrule"}

    # Forbidden rule commands inside tabular body
    FORBIDDEN_RULES = {r"\hline", r"\vline", r"\cline"}

    def __init__(self, tex_file: str):
        self.tex_file = Path(tex_file).resolve()
        self.content = ""
        self.lines: list[str] = []
        self.issues: list[dict] = []

    def _load(self) -> bool:
        """Load the .tex file content."""
        if not self.tex_file.exists():
            self.issues.append(
                {
                    "line": 0,
                    "level": self.LEVEL_ERROR,
                    "priority": "P1",
                    "message": f"File not found: {self.tex_file}",
                    "category": "file",
                }
            )
            return False
        self.content = self.tex_file.read_text(encoding="utf-8", errors="replace")
        self.lines = self.content.split("\n")
        return True

    def check(self, fix_suggestions: bool = False) -> dict:
        """Run all table structure checks."""
        if not self._load():
            return self._result()

        self._check_booktabs_loaded()
        tables = self._find_table_environments()

        for table in tables:
            self._check_vertical_lines(table)
            self._check_rule_commands(table)
            self._check_caption_position(table)
            self._check_table_notes(table)
            self._check_number_precision(table)

        if fix_suggestions:
            for issue in self.issues:
                issue["fix"] = self._suggest_fix(issue)

        return self._result()

    def _result(self) -> dict:
        """Build result dictionary."""
        if not self.issues:
            status = "PASS"
        elif any(i["level"] == self.LEVEL_ERROR for i in self.issues):
            status = "FAIL"
        else:
            status = "WARNING"

        return {
            "status": status,
            "file": str(self.tex_file),
            "table_count": len(self._find_table_environments()),
            "issue_count": len(self.issues),
            "issues": self.issues,
        }

    def _check_booktabs_loaded(self) -> None:
        """Check if booktabs package is loaded."""
        has_booktabs = False
        for line in self.lines:
            stripped = line.split("%")[0]  # Ignore comments
            if re.search(r"\\usepackage(\[[^\]]*\])?\{.*booktabs.*\}", stripped):
                has_booktabs = True
                break
        if not has_booktabs and re.search(r"\\begin\{table\*?\}", self.content):
            self.issues.append(
                {
                    "line": 0,
                    "level": self.LEVEL_WARNING,
                    "priority": "P2",
                    "message": "booktabs package not loaded. Add \\usepackage{booktabs} for professional three-line tables.",
                    "category": "package",
                }
            )

    def _find_table_environments(self) -> list[dict]:
        """Find all table/table* environments with their line ranges."""
        tables = []
        pattern = re.compile(r"\\begin\{(table\*?)\}")
        end_pattern = re.compile(r"\\end\{(table\*?)\}")

        stack: list[dict] = []
        for i, line in enumerate(self.lines, 1):
            stripped = line.split("%")[0]
            for m in pattern.finditer(stripped):
                stack.append({"env": m.group(1), "start": i, "start_col": m.start()})
            for _m in end_pattern.finditer(stripped):
                if stack:
                    entry = stack.pop()
                    entry["end"] = i
                    entry["content"] = "\n".join(self.lines[entry["start"] - 1 : i])
                    tables.append(entry)

        return tables

    def _check_vertical_lines(self, table: dict) -> None:
        """Check for vertical lines in column specifications."""
        content = table["content"]
        # Find tabular column spec: \begin{tabular}{|c|c|c|}
        col_specs = re.findall(r"\\begin\{tabular\*?\}(?:\{[^}]*\})?\{([^}]+)\}", content)
        for spec in col_specs:
            if "|" in spec:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_ERROR,
                        "priority": "P1",
                        "message": f"Vertical lines detected in column spec: {{{spec}}}. Three-line tables must not have vertical lines.",
                        "category": "vertical_lines",
                    }
                )

        # Also check for \vline
        for i, line in enumerate(self.lines[table["start"] - 1 : table["end"]], table["start"]):
            stripped = line.split("%")[0]
            if r"\vline" in stripped:
                self.issues.append(
                    {
                        "line": i,
                        "level": self.LEVEL_ERROR,
                        "priority": "P1",
                        "message": "\\vline detected. Three-line tables must not have vertical lines.",
                        "category": "vertical_lines",
                    }
                )

    def _check_rule_commands(self, table: dict) -> None:
        """Check for correct rule commands (booktabs vs hline)."""
        content = table["content"]

        # Find tabular body
        tabular_match = re.search(
            r"\\begin\{tabular\*?\}(?:\{[^}]*\})?\{[^}]+\}(.*?)\\end\{tabular\*?\}",
            content,
            re.DOTALL,
        )
        if not tabular_match:
            return

        tabular_body = tabular_match.group(1)

        # Count booktabs rules
        toprule_count = len(re.findall(r"\\toprule", tabular_body))
        midrule_count = len(re.findall(r"\\midrule", tabular_body))
        bottomrule_count = len(re.findall(r"\\bottomrule", tabular_body))

        # Check for forbidden rules
        for i, line in enumerate(self.lines[table["start"] - 1 : table["end"]], table["start"]):
            stripped = line.split("%")[0]
            if r"\hline" in stripped:
                self.issues.append(
                    {
                        "line": i,
                        "level": self.LEVEL_WARNING,
                        "priority": "P1",
                        "message": "\\hline detected. Use \\toprule, \\midrule, \\bottomrule (booktabs) instead.",
                        "category": "hline",
                    }
                )
            if re.search(r"\\cline\{[^}]+\}", stripped):
                self.issues.append(
                    {
                        "line": i,
                        "level": self.LEVEL_INFO,
                        "priority": "P3",
                        "message": "\\cline detected. Consider \\cmidrule (booktabs) for partial rules under sub-headers.",
                        "category": "hline",
                    }
                )

        # Validate three-line structure
        if toprule_count == 0 and midrule_count == 0 and bottomrule_count == 0:
            # No booktabs at all — check if using hline
            hline_count = len(re.findall(r"\\hline", tabular_body))
            if hline_count > 0:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_WARNING,
                        "priority": "P1",
                        "message": f"Table uses \\hline ({hline_count}x) instead of booktabs commands. Replace with \\toprule/\\midrule/\\bottomrule.",
                        "category": "booktabs_missing",
                    }
                )
        else:
            if toprule_count != 1:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_WARNING,
                        "priority": "P2",
                        "message": f"Expected exactly 1 \\toprule, found {toprule_count}.",
                        "category": "rule_count",
                    }
                )
            if bottomrule_count != 1:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_WARNING,
                        "priority": "P2",
                        "message": f"Expected exactly 1 \\bottomrule, found {bottomrule_count}.",
                        "category": "rule_count",
                    }
                )

    def _check_caption_position(self, table: dict) -> None:
        """Check that caption appears before tabular environment."""
        content = table["content"]

        caption_pos = -1
        tabular_pos = -1

        caption_match = re.search(r"\\caption", content)
        tabular_match = re.search(r"\\begin\{tabular\*?\}", content)

        if caption_match:
            caption_pos = caption_match.start()
        if tabular_match:
            tabular_pos = tabular_match.start()

        if caption_pos < 0:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_WARNING,
                    "priority": "P2",
                    "message": "No \\caption found in table environment.",
                    "category": "caption",
                }
            )
        elif tabular_pos >= 0 and caption_pos > tabular_pos:
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_WARNING,
                    "priority": "P2",
                    "message": "Caption should appear above the table (before \\begin{tabular}), not below.",
                    "category": "caption_position",
                }
            )

    def _check_table_notes(self, table: dict) -> None:
        """Check table note format if present."""
        content = table["content"]

        # Look for common note patterns
        has_note = False
        if re.search(r"\\item\s+Note\.", content):
            has_note = True
        if re.search(r"\\item\s+注[：:]", content):
            has_note = True
        if re.search(r"\\footnotesize\s*Note\.", content):
            has_note = True
        if re.search(r"\\footnotesize\s*注[：:]", content):
            has_note = True

        # Check if there are significance markers but no note explaining them
        if (
            re.search(r"\*\*?\*?", content)
            and not has_note
            and re.search(r"\d+\.?\d*\s*\*{1,3}", content)
        ):
            self.issues.append(
                {
                    "line": table["start"],
                    "level": self.LEVEL_INFO,
                    "priority": "P3",
                    "message": "Statistical significance markers (*/**/ ***) detected but no table note defining them. Add a note: 'Note. * p<0.05; ** p<0.01; *** p<0.001.'",
                    "category": "table_note",
                }
            )

    def _check_number_precision(self, table: dict) -> None:
        """Check for inconsistent decimal precision within columns."""
        content = table["content"]

        # Extract data rows (lines between \midrule and \bottomrule)
        data_match = re.search(r"\\midrule(.*?)\\bottomrule", content, re.DOTALL)
        if not data_match:
            return

        data_section = data_match.group(1)
        rows = [r.strip() for r in data_section.split(r"\\") if r.strip()]

        if len(rows) < 2:
            return

        # Parse columns
        parsed_rows = []
        for row in rows:
            # Remove LaTeX commands for analysis
            cleaned = re.sub(r"\\textbf\{([^}]*)\}", r"\1", row)
            cleaned = re.sub(r"\\bfseries\s*", "", cleaned)
            cleaned = re.sub(r"\$[^$]*\$", "", cleaned)
            cells = [c.strip() for c in cleaned.split("&")]
            parsed_rows.append(cells)

        if not parsed_rows:
            return

        # Check each column for precision consistency
        n_cols = max(len(r) for r in parsed_rows)
        for col_idx in range(n_cols):
            decimals_seen: set[int] = set()
            for row in parsed_rows:
                if col_idx < len(row):
                    cell = row[col_idx].strip().rstrip("*")
                    # Extract numbers
                    nums = re.findall(r"\d+\.(\d+)", cell)
                    for n in nums:
                        decimals_seen.add(len(n))

            if len(decimals_seen) > 1:
                self.issues.append(
                    {
                        "line": table["start"],
                        "level": self.LEVEL_WARNING,
                        "priority": "P3",
                        "message": f"Inconsistent decimal precision in column {col_idx + 1}: found {sorted(decimals_seen)} decimal places. Use consistent precision within each column.",
                        "category": "precision",
                    }
                )

    def _suggest_fix(self, issue: dict) -> str:
        """Generate fix suggestion for an issue."""
        cat = issue.get("category", "")
        if cat == "vertical_lines":
            return "Remove all | characters from the column specification."
        if cat == "hline":
            return "Replace \\hline with \\toprule (first), \\midrule (after header), \\bottomrule (last)."
        if cat == "booktabs_missing":
            return "Add \\usepackage{booktabs} and replace \\hline with \\toprule/\\midrule/\\bottomrule."
        if cat == "caption_position":
            return "Move \\caption{...} before \\begin{tabular}."
        if cat == "precision":
            return "Align all values in the column to the same number of decimal places."
        if cat == "package":
            return "Add \\usepackage{booktabs} to the preamble."
        return ""

    def generate_report(self, result: dict) -> str:
        """Generate human-readable report."""
        lines = []
        lines.append("=" * 60)
        lines.append("Table Structure Check Report")
        lines.append("=" * 60)
        lines.append(f"File: {result['file']}")
        lines.append(f"Tables found: {result['table_count']}")
        lines.append(f"Status: {result['status']}")
        lines.append(f"Issues: {result['issue_count']}")

        if result["issues"]:
            lines.append("")
            lines.append("-" * 60)

            by_category: dict[str, list[dict]] = {}
            for issue in result["issues"]:
                cat = issue.get("category", "other")
                if cat not in by_category:
                    by_category[cat] = []
                by_category[cat].append(issue)

            for category, issues in sorted(by_category.items()):
                lines.append(f"\n[{category.upper()}] ({len(issues)} issues)")
                for issue in issues:
                    prefix = f"  Line {issue['line']}" if issue["line"] else "  Global"
                    lines.append(f"{prefix}: [{issue['level']}] {issue['message']}")
                    if issue.get("fix"):
                        lines.append(f"    Fix: {issue['fix']}")

        lines.append("")
        lines.append("=" * 60)
        return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(
        description="Table Structure Checker - three-line table compliance"
    )
    parser.add_argument("tex_file", help=".tex file to check")
    parser.add_argument(
        "--fix-suggestions", "-f", action="store_true", help="Include fix suggestions"
    )
    parser.add_argument("--json", "-j", action="store_true", help="Output in JSON format")

    args = parser.parse_args()

    if not Path(args.tex_file).exists():
        print(f"[ERROR] File not found: {args.tex_file}")
        sys.exit(1)

    checker = TableChecker(args.tex_file)
    result = checker.check(fix_suggestions=args.fix_suggestions)

    if args.json:
        print(json.dumps(result, indent=2))
    else:
        print(checker.generate_report(result))

    sys.exit(1 if result["status"] == "FAIL" else 0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Detect thesis template and report key requirements.

Usage:
    uv run python detect_template.py main.tex
    uv run python detect_template.py main.tex --json
"""

import argparse
import json
import re
import sys
from pathlib import Path
from typing import Optional

try:
    from map_structure import ThesisStructureMapper
except ImportError:
    sys.path.append(str(Path(__file__).parent))
    from map_structure import ThesisStructureMapper

TEMPLATE_REFERENCE_FILES = {
    "thuthesis": "tsinghua.md",
    "pkuthss": "pku.md",
    "ctexbook": "generic.md",
    "ustcthesis": "generic.md",
    "fduthesis": "generic.md",
}


def _reference_dir() -> Path:
    return Path(__file__).resolve().parent.parent / "references" / "UNIVERSITIES"


def _reference_file(template_id: Optional[str]) -> Optional[Path]:
    if not template_id:
        template_id = "ctexbook"
    file_name = TEMPLATE_REFERENCE_FILES.get(template_id)
    if not file_name:
        return None
    path = _reference_dir() / file_name
    return path if path.exists() else None


def _extract_key_requirements(md_path: Path) -> list[str]:
    try:
        lines = md_path.read_text(encoding="utf-8", errors="ignore").splitlines()
    except Exception:
        return []

    in_section = False
    subsection = None
    requirements: list[str] = []

    for line in lines:
        if line.startswith("## "):
            title = line[3:].strip()
            in_section = "特殊格式要求" in title or "注意事项" in title
            subsection = None
            continue

        if line.startswith("### "):
            subsection = line[4:].strip()
            continue

        if not in_section:
            continue

        stripped = line.strip()
        if not stripped:
            continue

        is_bullet = stripped.startswith(("-", "*")) or re.match(r"^\d+\.", stripped)
        if not is_bullet:
            continue

        text = re.sub(r"^[-*]\s*", "", stripped)
        text = re.sub(r"^\d+\.\s*", "", text)
        if subsection:
            requirements.append(f"{subsection}: {text}")
        else:
            requirements.append(text)

    return requirements


def main() -> None:
    parser = argparse.ArgumentParser(description="Detect thesis template")
    parser.add_argument("tex_file", help="Main .tex file")
    parser.add_argument("--json", action="store_true", help="Output in JSON format")
    args = parser.parse_args()

    tex_path = Path(args.tex_file)
    if not tex_path.exists():
        print(f"[ERROR] File not found: {args.tex_file}", file=sys.stderr)
        sys.exit(1)

    mapper = ThesisStructureMapper(str(tex_path))
    mapper.map()

    template_id = mapper.template
    template_info = mapper.get_template_info() or {}
    ref_path = _reference_file(template_id)
    key_requirements = _extract_key_requirements(ref_path) if ref_path else []

    result = {
        "template": template_id or "unknown",
        "name": template_info.get("name"),
        "figure_format": template_info.get("figure_format"),
        "reference_file": str(ref_path) if ref_path else None,
        "key_requirements": key_requirements,
    }

    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=False))
        return

    print(f"Template: {result['template']}")
    if result["name"]:
        print(f"Name: {result['name']}")
    if result["figure_format"]:
        print(f"Figure format: {result['figure_format']}")
    if result["reference_file"]:
        print(f"Reference: {result['reference_file']}")
    if result["key_requirements"]:
        print("Key requirements:")
        for item in result["key_requirements"]:
            print(f"  - {item}")
    else:
        print("Key requirements: (not found)")


if __name__ == "__main__":
    main()

"""
Document Parsers for Chinese Academic Thesis
Support for LaTeX and Typst document parsing.
"""

import re
from abc import ABC, abstractmethod
from typing import Any


class DocumentParser(ABC):
    """Abstract base class for document parsers."""

    @abstractmethod
    def split_sections(self, content: str) -> dict[str, tuple[int, int]]:
        pass

    @abstractmethod
    def extract_visible_text(self, line: str) -> str:
        pass

    @abstractmethod
    def get_comment_prefix(self) -> str:
        pass

    def extract_headings(self, content: str) -> list[dict[str, Any]]:
        """Return heading nodes in document order.

        Parsers that support fine-grained heading inspection should override this.
        """
        return []


class LatexParser(DocumentParser):
    """Parser for Chinese LaTeX Thesis."""

    HEADING_PATTERN = re.compile(
        r"\\(?P<command>chapter|section|subsection|subsubsection|paragraph)\*?"
        r"(?:\[[^\]]*\])?\{(?P<title>[^}]*)\}"
    )

    HEADING_LEVELS = {
        "chapter": 1,
        "section": 2,
        "subsection": 3,
        "subsubsection": 4,
        "paragraph": 5,
    }

    # Chinese Section patterns
    SECTION_PATTERNS = {
        "abstract": r"\\chapter{摘要}|\\section{摘要}",
        "introduction": r"\\chapter{绪论}|\\chapter{引言}|\\section{绪论}|\\section{引言}",
        "contribution": r"\\chapter{(?:创新点|主要贡献)}|\\section{(?:创新点|主要贡献)}",
        "related": r"\\chapter{相关工作}|\\section{相关工作}|\\section{文献综述}",
        "method": r"\\chapter{.*?(?:方法|原理|设计)}",
        "experiment": r"\\chapter{.*?(?:实验|实现|测试)}|\\section{.*?(?:实验|实现)}",
        "result": r"\\chapter{.*?(?:结果|性能)}|\\section{.*?(?:结果|性能)}",
        "discussion": r"\\chapter{.*?(?:讨论|分析)}|\\section{.*?(?:讨论|分析)}",
        "conclusion": r"\\chapter{结论}|\\chapter{总结与展望}|\\section{结论}",
    }

    PRESERVE_PATTERNS = [
        r"\\cite{[^}]+}",  # Citations
        r"\\ref{[^}]+}",  # References
        r"\\label{[^}]+}",  # Labels
        r"\\eqref{[^}]+}",  # Equation references
        r"\\autoref{[^}]+}",  # Auto references
        r"\$\$[^$]*\$\$",  # Display math
        r"\$[^$]*\$",  # Inline math
        r"\\begin{equation}.*?\\end{equation}",  # Equations
        r"\\begin{align}.*?\\end{align}",  # Align environments
        r"\\begin{.*?}.*?\\end{.*?}",  # Generic environments
        r"\\includegraphics(?:\[[^]]*\])?\{[^}]+\}",  # Images
        r"\\caption{[^}]+}",  # Captions
    ]

    def get_comment_prefix(self) -> str:
        return "%"

    def split_sections(self, content: str) -> dict[str, tuple[int, int]]:
        lines = content.split("\n")
        sections = {}
        current_section = "preamble"
        start_line = 0

        for i, line in enumerate(lines, 1):
            for section_name, pattern in self.SECTION_PATTERNS.items():
                if re.search(pattern, line, re.IGNORECASE):
                    if current_section != "preamble":
                        sections[current_section] = (start_line, i - 1)
                    current_section = section_name
                    start_line = i
                    break

        if current_section != "preamble":
            sections[current_section] = (start_line, len(lines))

        return sections

    def extract_visible_text(self, line: str) -> str:
        temp_line = line
        preserved = []

        for pattern in self.PRESERVE_PATTERNS:
            matches = list(re.finditer(pattern, temp_line, re.DOTALL))
            for match in reversed(matches):
                preserved.append(
                    {"start": match.start(), "end": match.end(), "text": match.group()}
                )
                placeholder = " " * (match.end() - match.start())
                temp_line = temp_line[: match.start()] + placeholder + temp_line[match.end() :]

        preserved.sort(key=lambda x: x["start"])

        visible_parts = []
        last_end = 0

        for item in preserved:
            if item["start"] > last_end:
                visible_parts.append(temp_line[last_end : item["start"]])
            last_end = item["end"]

        if last_end < len(temp_line):
            visible_parts.append(temp_line[last_end:])

        return " ".join(visible_parts).strip()

    def extract_headings(self, content: str) -> list[dict[str, Any]]:
        headings: list[dict[str, Any]] = []
        for line_no, line in enumerate(content.split("\n"), 1):
            stripped = line.strip()
            if not stripped or stripped.startswith(self.get_comment_prefix()):
                continue
            match = self.HEADING_PATTERN.search(stripped)
            if not match:
                continue
            command = match.group("command")
            headings.append(
                {
                    "line": line_no,
                    "level": self.HEADING_LEVELS[command],
                    "command": command,
                    "title": match.group("title").strip(),
                }
            )
        return headings


class TypstParser(DocumentParser):
    """Parser for Chinese Typst Thesis."""

    HEADING_PATTERN = re.compile(r"^(?P<marks>={1,5})\s+(?P<title>.+?)\s*$")

    # Chinese Section patterns for Typst
    # e.g. = 摘要, = 绪论
    SECTION_PATTERNS = {
        "abstract": r"^=\s+摘要",
        "introduction": r"^=\s+(?:绪论|引言)",
        "contribution": r"^=\s+(?:创新点|主要贡献)",
        "related": r"^=\s+(?:相关工作|文献综述)",
        "method": r"^=\s+.*(?:方法|原理|设计)",
        "experiment": r"^=\s+.*(?:实验|实现|测试)",
        "result": r"^=\s+.*(?:结果|性能)",
        "discussion": r"^=\s+.*(?:讨论|分析)",
        "conclusion": r"^=\s+.*(?:结论|总结与展望)",
    }

    PRESERVE_PATTERNS = [
        r"@[a-zA-Z0-9_-]+",  # Citations
        r"#cite\([^)]+\)",
        r"#figure\([^)]+\)",
        r"#table\([^)]+\)",
        r"\$[^$]+\$",
        r"//.*",
        r"/\*.*?\*/",
        r"<[a-zA-Z0-9_-]+>",
        r"#link\([^)]+\)",
    ]

    def get_comment_prefix(self) -> str:
        return "//"

    def split_sections(self, content: str) -> dict[str, tuple[int, int]]:
        lines = content.split("\n")
        sections = {}
        current_section = "preamble"
        start_line = 0

        for i, line in enumerate(lines, 1):
            line = line.strip()
            if line.startswith("//"):
                continue

            for section_name, pattern in self.SECTION_PATTERNS.items():
                if re.search(pattern, line):
                    if current_section != "preamble":
                        sections[current_section] = (start_line, i - 1)
                    current_section = section_name
                    start_line = i
                    break

        if current_section != "preamble":
            sections[current_section] = (start_line, len(lines))

        return sections

    def extract_visible_text(self, line: str) -> str:
        temp_line = line
        if "//" in temp_line:
            temp_line = temp_line.split("//")[0]

        preserved = []
        for pattern in self.PRESERVE_PATTERNS:
            matches = list(re.finditer(pattern, temp_line, re.DOTALL))
            for match in reversed(matches):
                preserved.append(
                    {"start": match.start(), "end": match.end(), "text": match.group()}
                )
                placeholder = " " * (match.end() - match.start())
                temp_line = temp_line[: match.start()] + placeholder + temp_line[match.end() :]

        preserved.sort(key=lambda x: x["start"])

        visible_parts = []
        last_end = 0
        for item in preserved:
            if item["start"] > last_end:
                visible_parts.append(temp_line[last_end : item["start"]])
            last_end = item["end"]
        if last_end < len(temp_line):
            visible_parts.append(temp_line[last_end:])

        return " ".join(visible_parts).strip()

    def extract_headings(self, content: str) -> list[dict[str, Any]]:
        headings: list[dict[str, Any]] = []
        for line_no, line in enumerate(content.split("\n"), 1):
            stripped = line.strip()
            if not stripped or stripped.startswith(self.get_comment_prefix()):
                continue
            match = self.HEADING_PATTERN.match(stripped)
            if not match:
                continue
            headings.append(
                {
                    "line": line_no,
                    "level": len(match.group("marks")),
                    "command": "heading",
                    "title": match.group("title").strip(),
                }
            )
        return headings


def get_parser(file_path: Any) -> DocumentParser:
    """Factory method to get appropriate parser."""
    path_str = str(file_path).lower()
    if path_str.endswith(".typ"):
        return TypstParser()
    return LatexParser()


def _normalize_whitespace(text: str) -> str:
    """Collapse whitespace to single spaces."""
    return re.sub(r"\s+", " ", text).strip()


def _strip_latex_markup(text: str) -> str:
    """Remove LaTeX commands from text, keeping content."""
    text = re.sub(r"\\[a-zA-Z]+\*?(?:\[[^\]]*\])*\{([^}]*)\}", r"\1", text)
    text = re.sub(r"\\[a-zA-Z]+\*?", "", text)
    text = re.sub(r"[{}]", "", text)
    return _normalize_whitespace(text)


def extract_title(content: str) -> str:
    """Extract document title from Chinese LaTeX thesis source.

    Supports \\ctitle, \\title commands commonly used in Chinese thesis templates.
    """
    # Chinese title: \ctitle{...}
    ctitle = re.search(r"\\ctitle\{(.+?)\}", content, re.DOTALL)
    if ctitle:
        return _strip_latex_markup(ctitle.group(1))

    # Standard: \title{...}
    title = re.search(r"\\title(?:\[[^\]]*\])?\{(.+?)\}", content, re.DOTALL)
    if title:
        return _strip_latex_markup(title.group(1))

    return ""


def extract_abstract(content: str) -> str:
    """Extract abstract text from Chinese LaTeX thesis source.

    Supports \\cabstract, \\begin{cabstract}, \\begin{abstract} environments.
    """
    # Chinese abstract environment: \begin{cabstract}...\end{cabstract}
    cab = re.search(r"\\begin{cabstract}(.*?)\\end{cabstract}", content, re.DOTALL)
    if cab:
        return _strip_latex_markup(cab.group(1))

    # Standard abstract environment
    ab = re.search(r"\\begin{abstract}(.*?)\\end{abstract}", content, re.DOTALL)
    if ab:
        return _strip_latex_markup(ab.group(1))

    # Section-based: \chapter{摘要} or \section{摘要}
    sec = re.search(
        r"\\(?:chapter|section)\{摘要\}(.*?)(?=\\(?:chapter|section)\{|\\end\{document\}|\Z)",
        content,
        re.DOTALL,
    )
    if sec:
        return _strip_latex_markup(sec.group(1))

    return ""

#!/usr/bin/env python3
"""
BibTeX Verification Script - Check bibliography integrity
Includes static checks and online verification preparation.

Usage:
    uv run python verify_bib.py references.bib
    uv run python verify_bib.py references.bib --standard gb7714
    uv run python verify_bib.py references.bib --online-check
"""

import argparse
import json
import re
import sys
from pathlib import Path


class BibTeXVerifier:
    """Verify BibTeX file integrity and completeness."""

    REQUIRED_FIELDS = {
        "article": ["author", "title", "journal", "year"],
        "inproceedings": ["author", "title", "booktitle", "year"],
        "book": ["author", "title", "publisher", "year"],
    }

    GB7714_RECOMMENDED = ["doi", "url", "urldate"]

    def __init__(
        self,
        bib_file: str,
        standard: str = "default",
        online: bool = False,
        email: str | None = None,
        online_timeout: float = 10.0,
    ):
        self.bib_file = Path(bib_file).resolve()
        self.standard = standard
        self.entries = []
        self.issues = []
        self.online = online
        self.email = email
        self.online_timeout = online_timeout

    def parse(self) -> list[dict]:
        """Parse BibTeX file."""
        try:
            content = self.bib_file.read_text(encoding="utf-8", errors="ignore")
        except Exception as e:
            self.issues.append({"type": "file_error", "message": str(e)})
            return []

        entries = []
        # Robust regex for entries
        entry_pattern = r"@(\w+)\s*{\s*([^,]+)\s*,([^@]*?)(?=\n\s*@|\Z)"

        for match in re.finditer(entry_pattern, content, re.DOTALL):
            entries.append(
                {
                    "type": match.group(1).lower(),
                    "key": match.group(2).strip(),
                    "fields": self._parse_fields(match.group(3)),
                    "raw": match.group(0),
                }
            )

        self.entries = entries
        return entries

    def _parse_fields(self, fields_str: str) -> dict[str, str]:
        fields = {}
        # Parse field = {value} or "value" or number
        field_pattern = r'(\w+)\s*=\s*(?:\{([^^{}]*(?:\{[^{}]*\}[^{}]*)*)\}|"([^"]*)"|(\d+))'
        for match in re.finditer(field_pattern, fields_str):
            name = match.group(1).lower()
            val = match.group(2) or match.group(3) or match.group(4) or ""
            fields[name] = val.strip()
        return fields

    def verify(self) -> dict:
        if not self.entries:
            self.parse()

        results = {
            "total_entries": len(self.entries),
            "valid_entries": 0,
            "issues": [],
            "status": "PASS",
            "needs_online_check": [],
        }

        for entry in self.entries:
            entry_issues = self._verify_entry(entry)

            # Check for missing identifiers (DOI/URL)
            if "doi" not in entry["fields"] and "url" not in entry["fields"]:
                results["needs_online_check"].append(
                    {
                        "key": entry["key"],
                        "title": entry["fields"].get("title", "Unknown Title"),
                        "author": entry["fields"].get("author", "Unknown Author"),
                    }
                )

            if entry_issues:
                results["issues"].extend(entry_issues)
            else:
                results["valid_entries"] += 1

        if results["issues"]:
            has_errors = any(i["severity"] == "error" for i in results["issues"])
            results["status"] = "FAIL" if has_errors else "WARNING"

        # Online verification (when --online and online_bib_verify is available)
        if self.online:
            try:
                from online_bib_verify import OnlineBibVerifier

                online_verifier = OnlineBibVerifier(
                    polite_email=self.email,
                    timeout=self.online_timeout,
                )
                for entry_info in results["needs_online_check"]:
                    entry_dict = {
                        "key": entry_info["key"],
                        "title": entry_info.get("title", ""),
                        "author": entry_info.get("author", ""),
                    }
                    for entry in self.entries:
                        if entry["key"] == entry_info["key"]:
                            entry_dict.update(entry["fields"])
                            break
                    result = online_verifier.verify_entry(entry_dict)
                    if result.status == "mismatch":
                        for m in result.mismatches:
                            results["issues"].append(
                                {
                                    "key": result.bib_key,
                                    "type": "metadata_mismatch",
                                    "severity": "error",
                                    "message": f"Online verification mismatch: {m}",
                                }
                            )
                    elif result.status == "not_found":
                        results["issues"].append(
                            {
                                "key": result.bib_key,
                                "type": "not_found_online",
                                "severity": "warning",
                                "message": "Entry not found in online databases",
                            }
                        )
                    elif result.status == "verified" and result.suggested_doi:
                        results["issues"].append(
                            {
                                "key": result.bib_key,
                                "type": "doi_suggestion",
                                "severity": "warning",
                                "message": f"Consider adding DOI: {result.suggested_doi}",
                            }
                        )
            except ImportError:
                print("# Warning: online_bib_verify.py not found, skipping online verification")

        return results

    def _verify_entry(self, entry: dict) -> list[dict]:
        issues = []
        entry_type = entry["type"]
        entry_key = entry["key"]
        fields = entry["fields"]

        if entry_type in self.REQUIRED_FIELDS:
            for field in self.REQUIRED_FIELDS[entry_type]:
                if field not in fields or not fields[field]:
                    if field == "author" and "editor" in fields:
                        continue
                    issues.append(
                        {
                            "key": entry_key,
                            "type": "missing_field",
                            "field": field,
                            "severity": "error",
                            "message": f"Missing required field '{field}'",
                        }
                    )

        # Title case check (simplified)
        if (
            "title" in fields
            and re.search(r"\b[A-Z]{2,}\b", fields["title"])
            and "{" not in fields["title"]
        ):
            issues.append(
                {
                    "key": entry_key,
                    "type": "caps",
                    "severity": "warning",
                    "message": "Unprotected uppercase in title",
                }
            )

        return issues

    def generate_report(self, result: dict) -> str:
        lines = []
        lines.append(f"BibTeX Check: {self.bib_file}")
        lines.append(f"Status: {result['status']}")

        if result["issues"]:
            lines.append("\nIssues:")
            for issue in result["issues"]:
                lines.append(f"  [{issue['severity'].upper()}] @{issue['key']}: {issue['message']}")

        if result["needs_online_check"]:
            lines.append(
                f"\n[INFO] {len(result['needs_online_check'])} entries missing DOI/URL (Use --online-check to export list)"
            )

        return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description="BibTeX Verification")
    parser.add_argument("bib_file", help=".bib file")
    parser.add_argument("--standard", choices=["default", "gb7714"], default="default")
    parser.add_argument(
        "--online-check", action="store_true", help="Generate list for online verification"
    )
    parser.add_argument(
        "--online",
        action="store_true",
        help="Enable online verification via CrossRef/Semantic Scholar",
    )
    parser.add_argument("--email", help="Email for CrossRef polite pool (faster rate limits)")
    parser.add_argument(
        "--online-timeout",
        type=float,
        default=10.0,
        help="Timeout per API request in seconds",
    )
    parser.add_argument("--output", help="Output file for online check JSON")

    args = parser.parse_args()

    if not Path(args.bib_file).exists():
        print("File not found.")
        sys.exit(1)

    verifier = BibTeXVerifier(
        args.bib_file,
        args.standard,
        online=getattr(args, "online", False),
        email=getattr(args, "email", None),
        online_timeout=getattr(args, "online_timeout", 10.0),
    )
    result = verifier.verify()

    if args.online_check:
        output_file = args.output or "verification_needed.json"
        with open(output_file, "w", encoding="utf-8") as f:
            json.dump(result["needs_online_check"], f, indent=2, ensure_ascii=False)
        print(f"Exported {len(result['needs_online_check'])} entries to {output_file}")
        print("Agent instructions: Use 'google_web_search' for these titles to find DOIs.")
    else:
        print(verifier.generate_report(result))

    if result["status"] == "FAIL":
        sys.exit(1)


if __name__ == "__main__":
    main()
